{
  "type": "object",
  "required": [
    "accountId",
    "scheduledPaymentId",
    "scheduledType",
    "scheduledPaymentDateTime",
    "instructedAmount"
  ],
  "properties": {
    "accountId": {
      "type": "string",
      "description": "The account identifer for the account from which the scheduled payment is made."
    },
    "scheduledPaymentId": {
      "type": "string",
      "description": "Unique identifier for the scheduled payment."
    },
    "accountHolderName": {
      "$ref": "#/components/schemas/AccountHolderName"
    },
    "accountHolderShortName": {
      "$ref": "#/components/schemas/AccountHolderShortName"
    },
    "scheduledType": {
      "description": "Specifies the type of scheduled payment date provided under ScheduledPaymentDateTime.\n  Encoded with allowable values of:\n  \"Arrival\" - User1 specifies the date for the arrival of funds in the beneficiary (Creditor) account\n  \"Execution\" - User1 specifies the date which the payment needs to be executed from the User 1 (Debtor) account.\n",
      "type": "string",
      "enum": [
        "Arrival",
        "Execution"
      ]
    },
    "scheduledPaymentDateTime": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEDateTime"
        },
        {
          "description": "The date and time of the scheduled payment."
        }
      ]
    },
    "creditorReference": {
      "type": "string",
      "description": "The creditor reference for the scheduled payment."
    },
    "debtorReference": {
      "type": "string",
      "description": "The debitor reference for the scheduled payment."
    },
    "instructedAmount": {
      "$ref": "#/components/schemas/OBActiveOrHistoricCurrencyAndAmount_8"
    },
    "creditorAgent": {
      "$ref": "#/components/schemas/AEBranchAndFinancialInstitutionIdentification5_1"
    },
    "creditorAccount": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AECashAccount5_0"
      },
      "description": "Provides the list of details to identify the beneficiary account."
    }
  },
  "description": "Scheduled Payments for a specific AccountId"
}

{
  "type": "string",
